  "name": "stock_news",
  "description": "Latest headlines for one stock ticker (Yahoo Finance), newest first.",
  "args": {
   "ticker": "str \u2014 e.g. NVDA",
   "limit": "int (optional) \u2014 max items"
  }
 },
 {
  "name": "news_search",
  "description": "Search recent news headlines across outlets (Google News + Bing News).",
  "args": {
   "query": "str \u2014 search words",
   "days": "int (optional) \u2014 how many days back",
   "limit": "int (optional) \u2014 max items"
  }
 },
 {
  "name": "fetch_page",
  "description": "Read the main text of a web page (e.g. a news article URL from a search result).",
  "args": {
   "url": "str \u2014 http(s) URL",
   "max_chars": "int (optional) \u2014 max characters of text"
  }
 },
 {
  "name": "price_history",
  "description": "Recent daily closes and simple return/volatility stats for a ticker.",
  "args": {
   "ticker": "str \u2014 e.g. NVDA",
   "days": "int (optional) \u2014 trading days"
  }
 },
 {
  "name": "sec_filings",
  "description": "Most recent SEC filings for a ticker, with acceptance timestamps and links.",
  "args": {
   "ticker": "str \u2014 e.g. NVDA",
   "forms": "list[str] (optional) \u2014 form types",
   "limit": "int (optional) \u2014 max filings"
  }
 },
 {
  "name": "filing_documents",
  "description": "List the documents inside one filing (e.g. EX-99.1, the earnings press release).",
  "args": {
   "url": "str \u2014 a filing URL from sec_filings_as_of"
  }
 },
 {
  "name": "read_filing",
  "description": "Read the text of an SEC filing document accepted before the decision time.",
  "args": {
   "url": "str \u2014 https://www.sec.gov/Archives/edgar/data/... URL",
   "max_chars": "int (optional) \u2014 max characters of text"
  }
 }
]

Reply with ONLY one JSON object, either
  {"thought": "<one-sentence plan>", "actions": [{"tool": "<name>", "args": {...}}]}
    (up to 4 actions; they run in parallel)
or
  {"thought": "<one-sentence summary>", "final": {"p_up": <number 0-1>,
    "reason": "<2-4 sentences citing the evidence>", "sources": ["<url>"]}}

